import base64
import json
import subprocess
import sys
import zipfile
from pathlib import Path

SEGMENTS_JSON = '[{"id":"037","text":"For the E side of the state, the rotations are different."},{"id":"039","text":"First, SHA-256 computes T one from H, the sigma function of E, the Choose function, a round constant, and the current message word."},{"id":"040","text":"Then T two is computed from the sigma function of A and the Majority function."},{"id":"054","text":"Let\'s hash the text A, B, C and watch every byte move."},{"id":"090","text":"For this deliberately tiny function, the letter Y and the string containing a space followed by the at sign, both produce the same eight-bit result: hex eight A."}]'
REF_OPUS_B64 = ""


def sh(cmd):
    print("+", " ".join(cmd), flush=True)
    return subprocess.run(cmd, check=True)


sh([sys.executable, "-m", "pip", "install", "-q", "-U", "voxcpm", "soundfile"])

import torch  # noqa: E402
import soundfile as sf  # noqa: E402
from voxcpm import VoxCPM  # noqa: E402

print("GPU count:", torch.cuda.device_count(), flush=True)

work = Path("/kaggle/working")
out_dir = work / "audio"
out_dir.mkdir(exist_ok=True)

ref_opus = work / "ref.opus"
ref_wav = work / "reference.wav"
ref_opus.write_bytes(base64.b64decode(REF_OPUS_B64))
sh([
    "ffmpeg", "-y", "-v", "error",
    "-i", str(ref_opus),
    "-vn", "-ac", "1", "-ar", "16000", "-c:a", "pcm_s16le",
    str(ref_wav),
])

try:
    model = VoxCPM.from_pretrained(
        "openbmb/VoxCPM2", load_denoiser=True, device="cuda", optimize=True,
    )
except Exception as e:
    print("optimize=True load failed, retrying without optimize:", repr(e), flush=True)
    model = VoxCPM.from_pretrained(
        "openbmb/VoxCPM2", load_denoiser=True, device="cuda", optimize=False,
    )

segments = json.loads(SEGMENTS_JSON)
sr = model.tts_model.sample_rate
durations = {}
failed = []

for i, seg in enumerate(segments):
    sid = str(seg["id"]).zfill(3)
    text = seg["text"]
    if not text.strip():
        durations[sid] = None
        print(f"[{i + 1}/{len(segments)}] seg_{sid}: (no narration, skipped)", flush=True)
        continue
    ok = False
    for attempt in range(3):
        try:
            wav = model.generate(
                text=text,
                reference_wav_path=str(ref_wav),
                cfg_value=2.0,
                inference_timesteps=20,
                normalize=True,
                denoise=True,
                retry_badcase=True,
                retry_badcase_max_times=3,
                retry_badcase_ratio_threshold=6.0,
            )
            sf.write(str(out_dir / f"seg_{sid}.wav"), wav, sr)
            durations[sid] = round(len(wav) / sr, 3)
            print(f"[{i + 1}/{len(segments)}] seg_{sid}: {durations[sid]:.2f}s", flush=True)
            ok = True
            break
        except Exception as e:
            print(f"seg_{sid} attempt {attempt + 1} failed: {repr(e)}", flush=True)
            torch.cuda.empty_cache()
    if not ok:
        durations[sid] = None
        failed.append(sid)
    if (i + 1) % 10 == 0:
        torch.cuda.empty_cache()

(out_dir / "durations.json").write_text(json.dumps(durations, indent=1))
print("failed:", failed, flush=True)

zip_path = work / "audio.zip"
with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_STORED) as z:
    for f in sorted(out_dir.iterdir()):
        z.write(f, f"audio/{f.name}")

total = sum(v for v in durations.values() if v)
print(f"DONE segments={len(durations)} failed={len(failed)} total_audio={total:.1f}s", flush=True)
